			const settings = await user.getSettings(uid);
			if (!isPrivileged && (settings && !settings.showemail)) {
				uid = 0;
			}
		}
	}
	if (!uid) {
		return null;
	}
	return await userController.getUserDataByUID(callerUid, uid);
